import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, length, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, BoxGeometry, PointLight, DirectionalLight } = THREE;

  const root = new Group();
  root.name = 'nav-dock';

  const colors = config.intent?.visualSpec?.colors ?? {};
  const accentColor = colors.accent ?? '#ff2a38';
  const paperColor = colors.paper ?? '#e8ecf2';
  const inactiveColor = '#a6adba';

  // Spec copy — must render verbatim from textContent items
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const entries = textItems.map((it) => it.text);
  if (entries.length === 0) {
    entries.push('HOME', 'FEATURES', 'COLLECTION', 'PRICING', 'JOURNAL');
  }
  const hubs = ['hub-home', 'hub-features', 'hub-collection', 'hub-pricing', 'hub-journal'];
  const NAV_COUNT = entries.length;
  const cellSpacing = 0.68;
  const initX = -(NAV_COUNT - 1) * cellSpacing / 2;

  /* ---------- Backdrop gradient plane ---------- */
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  backdropMat.colorNode = mix(vec3('#1b1b23'), vec3('#101015'), uv().y);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  /* ---------- Node-local lights (scene provides ambient + key) ---------- */
  const accentRim = new PointLight(new THREE.Color(accentColor), 0.9, 6, 1.6);
  accentRim.position.set(0.6, 0.4, -1.4);
  root.add(accentRim);

  const backFill = new DirectionalLight(0xffffff, 0.55);
  backFill.position.set(-2.0, -0.4, -1.5);
  backFill.target.position.set(0, 0, 0);
  root.add(backFill);
  root.add(backFill.target);

  /* ---------- Contact shadow plane below rail ---------- */
  const shadowGeo = new PlaneGeometry(4.4, 1.2);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const sCenter = uv().sub(vec3(0.5, 0.5, 0.0));
  const stretched = vec3(sCenter.x.mul(1.0), sCenter.y.mul(2.4), 0.0);
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = smoothstep(0.55, 0.0, length(stretched)).mul(0.35);
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -0.31, 0.04);
  root.add(shadow);

  /* ---------- Machined rail ---------- */
  const railGeo = new BoxGeometry(3.6, 0.5, 0.06);
  const railMat = new MeshStandardNodeMaterial({
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    anisotropy: 0.6
  });
  railMat.colorNode = mix(vec3('#1b1b23'), vec3('#101015'), uv().y);
  const rail = new Mesh(railGeo, railMat);
  rail.position.set(0, 0, 0.15);
  root.add(rail);

  /* ---------- Active underline bar ---------- */
  const barGeo = new PlaneGeometry(0.28, 0.025);
  const barIntensity = uniform(1.8);
  const barMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  barMat.colorNode = vec3(accentColor).mul(barIntensity);
  barMat.opacityNode = uniform(1.0);
  const bar = new Mesh(barGeo, barMat);
  bar.position.set(initX, -0.08, 0.22);
  root.add(bar);

  /* ---------- Nav entries ---------- */
  const navEntries = [];
  let activeIndex = 0;

  function setEntryText(e, content, color) {
    if (e.userData.textMesh) {
      e.remove(e.userData.textMesh);
    }
    const t = ctx.fontAtlas.createText(content, {
      fontSize: 13,
      color,
      align: 'center'
    });
    t.position.set(0, -0.02, 0.03);
    e.add(t);
    e.userData.textMesh = t;
  }

  for (let i = 0; i < NAV_COUNT; i++) {
    const e = new Group();
    e.name = 'nav-entry-' + entries[i].toLowerCase();
    e.position.set(initX + i * cellSpacing, 0, 0.19);

    // Invisible hit area (raycast target)
    const hitGeo = new PlaneGeometry(0.6, 0.34);
    const hitMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
    hitMat.colorNode = vec3(0.0, 0.0, 0.0);
    hitMat.opacityNode = uniform(0.0);
    const hit = new Mesh(hitGeo, hitMat);
    hit.userData.isHit = true;
    e.add(hit);

    const initialColor = (i === 0) ? paperColor : inactiveColor;
    setEntryText(e, entries[i], initialColor);

    e.userData.index = i;
    e.userData.label = entries[i];
    e.userData.handlers = {
      click: () => {
        setActive(i);
        ctx.emit('navigate', { to: hubs[i] });
      },
      pointerenter: () => {
        if (i === activeIndex) return;
        setEntryText(e, entries[i], paperColor);
      },
      pointerleave: () => {
        if (i === activeIndex) return;
        setEntryText(e, entries[i], inactiveColor);
      },
      pointerdown: () => {
        gsap.to(e.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.in(2)' });
        gsap.to(e.position, { z: 0.16, duration: 0.12, ease: 'power2.out' });
      },
      pointerup: () => {
        gsap.to(e.scale, { x: 1.0, y: 1.0, duration: 0.4, ease: 'back.out(1.7)' });
        gsap.to(e.position, { z: 0.19, duration: 0.4, ease: 'power4.out' });
      }
    };

    root.add(e);
    navEntries.push(e);
  }

  /* ---------- setActive: crossfade entry colors + slide bar w/ overshoot ---------- */
  const activeTweens = [];
  function setActive(i) {
    if (i === activeIndex) return;
    const prev = activeIndex;
    activeIndex = i;

    if (navEntries[prev]) setEntryText(navEntries[prev], entries[prev], inactiveColor);
    setEntryText(navEntries[navEntries.length > 0 && i < navEntries.length ? i : 0], entries[i], paperColor);

    const targetX = initX + i * cellSpacing;
    activeTweens.forEach((t) => t.kill());
    activeTweens.length = 0;

    const t1 = gsap.to(bar.position, {
      x: targetX,
      duration: 0.26,
      ease: 'power3.out'
    });
    activeTweens.push(t1);

    // Weighted 1.04 overshoot settle on bar scale
    gsap.killTweensOf(bar.scale);
    const tl = gsap.timeline()
      .to(bar.scale, { x: 1.04, duration: 0.18, ease: 'power2.out' })
      .to(bar.scale, { x: 1.0, duration: 0.22, ease: 'power4.out' });
    activeTweens.push(tl);
  }

  /* ---------- Mount: rise-in entrance ---------- */
  root.position.y = 0.4;
  const entrance = gsap.timeline();
  entrance.to(root.position, { y: 0.0, duration: 0.7, ease: 'power3.out' });

  // Stagger nav entries fade-up (children stagger)
  navEntries.forEach((e, idx) => {
    e.scale.set(1, 0.0, 1);
    gsap.to(e.scale, {
      y: 1,
      duration: 0.5,
      delay: 0.25 + idx * 0.06,
      ease: 'power2.out'
    });
  });

  /* ---------- Idle: subtle breathing on rail (ONE slow transform) ---------- */
  const idle = gsap.to(rail.position, {
    y: 0.012,
    duration: 2.4,
    repeat: -1,
    yoyo: true,
    ease: 'sine.inOut'
  });

  /* ---------- Cleanup ---------- */
  root.userData.cleanup = () => {
    entrance.kill();
    idle.kill();
    activeTweens.forEach((t) => t.kill());
    activeTweens.length = 0;
    navEntries.forEach((e) => {
      gsap.killTweensOf(e.scale);
      gsap.killTweensOf(e.position);
      const hit = e.children.find((c) => c.userData.isHit);
      hit?.geometry?.dispose();
      hit?.material?.dispose();
      if (e.userData.textMesh) {
        e.userData.textMesh.geometry?.dispose?.();
        e.userData.textMesh.material?.dispose?.();
      }
    });
    gsap.killTweensOf(bar.position);
    gsap.killTweensOf(bar.scale);
    [backdropGeo, shadowGeo, railGeo, barGeo].forEach((g) => g.dispose());
    [backdropMat, shadowMat, railMat, barMat].forEach((m) => m.dispose());
    if (accentRim.dispose) accentRim.dispose();
    if (backFill.dispose) backFill.dispose();
  };

  root.userData.setActive = setActive;
  return root;
}
